/// <summary>
/// The <c>METDallasPicklistRegSalesConfirmService</c> class is a service class used for the MET Dallas picklist registration sales confirmation process.
/// </summary>
class METDallasPicklistRegSalesConfirmService extends SysOperationServiceBase
{
    METDallasPicklistRegSalesConfirmContract contract;

}

Method.Source:
/// <summary>
/// Processes the MET Dallas picklist registration sales confirmation.
/// </summary>
/// <param name = "_contract">Data contract.</param>
public void process(METDallasPicklistRegSalesConfirmContract _contract)
{
    contract = _contract;

    this.scheduleBatchTasks();
}

/// <summary>
/// Schedules batch tasks.
/// </summary>
private void scheduleBatchTasks()
{
    METDallasPicklistRegSalesConfirmContract metDataContract;
    SysOperationServiceController controller;
    BatchHeader batchHeader;
    container salesOrderCon;
    Set salesOrderSet;
    int bundlesize;
    int totalTasks;
    int counter;
    int taskNumber = 1;

    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::DallasPicklistRegistration);

    batchHeader = this.getCurrentBatchHeader();

    if (batchHeader == null)
    {
        batchHeader = batchHeader::construct();
    }

    totalTasks = contract.parmParallelTasksNumber();

    if (totalTasks <= 0)
    {
        totalTasks = 1;
    }

    salesOrderSet = this.getSalesOrderSet(contract.parmWMSOrderTransRouteSet());

    if (salesOrderSet.elements() == 0)
    {
        return;
    }

    procMetrics.setTotalCount(salesOrderSet.elements());
    procMetrics.beginTrace('Process started');
    procMetrics.startDescriptionTime(2, "@MET:DallasConfirmSalesOrdersScheduled");

    bundleSize = real2int(roundUp((salesOrderSet.elements() / totalTasks), 1.0));

    SetEnumerator setEnum = salesOrderSet.getEnumerator();

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        while (setEnum.moveNext())
        {
            SalesId salesId = setEnum.current();

            counter += 1;

            if (counter == 1)
            {
                salesOrderCon = conNull();
            }

            salesOrderCon += salesId;

            if (counter == bundlesize)
            {
                controller = new SysOperationServiceController(
                                            classStr(METPickingListRegistrationPostingJob),
                                            methodStr(METPickingListRegistrationPostingJob, salesOrdersConfirmInBundle));

                controller.parmDialogCaption(strFmt("@MET:DallasConfirmSalesOrdersSubTaskWithSO", taskNumber, salesId));

                metDataContract = controller.getDataContractObject() as METDallasPicklistRegSalesConfirmContract;
                metDataContract.parmSalesOrderCon(salesOrderCon);

                batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

                counter = 0;

                taskNumber++;
            }
        }

        if (counter > 0)
        {
            controller = new SysOperationServiceController(
                                            classStr(METPickingListRegistrationPostingJob),
                                            methodStr(METPickingListRegistrationPostingJob, salesOrdersConfirmInBundle));

            controller.parmDialogCaption(strFmt("@MET:DallasConfirmSalesOrdersSubTask", taskNumber));

            metDataContract = controller.getDataContractObject() as METDallasPicklistRegSalesConfirmContract;
            metDataContract.parmSalesOrderCon(salesOrderCon);

            batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);
        }

        batchHeader.save();
        procMetrics.endTrace();
    }
}

/// <summary>
/// Gets the sales order set from the WMS order transaction route set.
/// </summary>
/// <param name = "_wmsOrderTransRouteSet">WMS order trans route.</param>
/// <returns></returns>
private Set getSalesOrderSet(container _wmsOrderTransRouteSet)
{
    Set wmsOrderTransRouteSet;
    Set salesOrderSet;

    wmsOrderTransRouteSet = Set::create(_wmsOrderTransRouteSet);
    salesOrderSet = new Set(Types::String);

    SetEnumerator setEnum = wmsOrderTransRouteSet.getEnumerator();

    while (setEnum.moveNext())
    {
        WMSPickingRouteID routeId = setEnum.current();

        WMSPickingRoute route = WMSPickingRoute::find(routeId);

        boolean canAddRecord = (   route.transType == InventTransType::Sales
                                && route.expeditionStatus == WMSExpeditionStatus::Complete
                                && METSalesTable::findBySalesId(route.transRefId).OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted);

        if (canAddRecord)
        {
            salesOrderSet.add(route.transRefId);
        }
    }

    return salesOrderSet;
}
